#!/usr/bin/env bash
# Build the consolefont tool for the T-Deck Plus (FDPIC uClibc dynamic).
# consolefont.c is generated by AppData/Local/Temp/opencode/make_consolefont.py
# (WSL side); it embeds the kernel VGA8x16/VGA8x8/7x14/VGA6x11 glyph data and
# applies it with the KDFONTOP ioctl on /dev/tty0 (the active VT).
# Run as "builder".
set -euo pipefail

W=$HOME/esp32s3/consolefont
B=$HOME/esp32s3/build
host=xtensa-esp32s3-linux-uclibcfdpic
prefix=$B/crosstool-NG/builds/$host/bin/$host

export XTENSA_GNU_CONFIG=$B/xtensa-dynconfig/esp32s3.so

mkdir -p "$W/out"
"$prefix-gcc" -std=c99 -Os -mfdpic -mauto-litpools -fPIC \
    -Wall -Wextra -Werror \
    -o "$W/out/consolefont" "$W/consolefont.c"
"$prefix-strip" "$W/out/consolefont"
"$prefix-size" "$W/out/consolefont"

echo "--- NEEDED ---"
"$prefix-readelf" -d "$W/out/consolefont" | grep NEEDED
echo "--- SHA256 ---"
sha256sum "$W/out/consolefont"
ls -l "$W/out/consolefont"
